async fn latest(config: PathBuf) -> anyhow::Result<CliSuccess<IngestionResponse<IngestionLocation>>> {
    let config = LoaderConfig::try_from(&config)?;
    let ingestion = ExposedDataPipeline::latest_ingestion(&config.data_dir).await?
        .map(|(path, ingestion_key)| IngestionLocation { ingestion_key, path });
    Ok(CliSuccess::new(IngestionResponse { ingestion }))
}

async fn copy_latest_raw(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<IngestionResponse<CopiedIngestion>>>
{
    let config = LoaderConfig::try_from(&config)?;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let ingestion = ExposedDataPipeline::copy_latest_raw(&config.data_dir, ingestion_key.clone()).await?
        .map(|(path, source_ingestion_key)| CopiedIngestion { source_ingestion_key, ingestion_key, path });
    Ok(CliSuccess::new(IngestionResponse { ingestion }))
}

async fn declarations(stage: String, config: PathBuf, ingestion_key: Option<IngestionKey>) -> Response {
    let stage = match DeclarationIngestionStage::from_str(&stage) {
        Ok(stage) => stage,
        Err(error) => return Err::<Response, _>(error).into_response(),
    };
    match stage {
        DeclarationIngestionStage::Fetch => fetch_declarations(config, ingestion_key).await.into_response(),
        DeclarationIngestionStage::Clean => clean_declarations(config, ingestion_key).await.into_response(),
        DeclarationIngestionStage::Resolve => resolve_declarations(config, ingestion_key).await.into_response(),
        DeclarationIngestionStage::Load => load_declarations(config, ingestion_key).await.into_response(),
    }
}

async fn fetch_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<StageAcknowledgement<DeclarationIngestionStage>>>
{
    let config = DeclarationFetcherConfig::try_from(&config)?;
    let data_config = DataConfig::from_env()?;
    let api = ParliamentApiClient::new(config.batch_size)?;
    let db = ExposedDatabase::new(&data_config.connection_string).await;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let fs = ExposedDataPipeline::new_with_ingestion_key(&config.data_dir, ingestion_key.clone())?;
    DeclarationFetcherService::new(db, api, fs).fetch_declarations().await?;
    Ok(CliSuccess::new(StageAcknowledgement {
        path: std::path::absolute(config.data_dir)?.join(ingestion_key.to_string()).join("raw/declarations"),
        ingestion_key,
        stage: DeclarationIngestionStage::Fetch,
    }))
}

async fn resolve_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<ResolvedDeclarations>>
{
    let ingestion_key = ingestion_key.ok_or_else(|| anyhow::anyhow!("declarations resolve requires --ingestion-key"))?;
    let config = DeclarationResolverConfig::try_from(&config)?;
    let storage = ExposedDataPipeline::open_cleaned_declarations(&config.data_dir, ingestion_key.clone())?;
    let scorer = WeldrsFunderScorer::new()?;
    let summary = DeclarationResolverService::new(storage, scorer, config.candidate_budget).resolve_declarations().await?;
    Ok(CliSuccess::new(ResolvedDeclarations {
        path: std::path::absolute(config.data_dir)?.join(ingestion_key.to_string()).join("resolved/declarations"),
        ingestion_key,
        observations: summary.observations,
        payments: summary.payments,
        pairs: summary.pairs,
    }))
}

async fn load_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<LoadedDeclarations>>
{
    let ingestion_key = ingestion_key.ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
    let config = LoaderConfig::try_from(&config)?;
    let data_config = DataConfig::from_env()?;
