    Ok(CliSuccess::new(LoadedDeclarations {
        ingestion_key, outcome: summary.outcome, declarations: summary.declarations,
        funders: summary.funders, funding_entries: summary.funding_entries,
    }))
}

async fn clean_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
