    -> anyhow::Result<CliSuccess<LoadedDeclarations>>
{
    let ingestion_key = ingestion_key.ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
    let config = LoaderConfig::try_from(&config)?;
    let data_config = DataConfig::from_env()?;
    let storage = ExposedDataPipeline::open_resolved_declarations(&config.data_dir, ingestion_key.clone())?;
    let db = ExposedDatabase::new(&data_config.connection_string).await;
    let summary = DeclarationLoaderService::new(storage, db).load_declarations().await?;
    Ok(CliSuccess::new(LoadedDeclarations {
        ingestion_key, outcome: summary.outcome, declarations: summary.declarations,
        funders: summary.funders, funding_entries: summary.funding_entries,
    }))
}

async fn clean_declarations(config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<CleanedDeclarations>>
{
    let ingestion_key = ingestion_key.ok_or_else(|| anyhow::anyhow!("declarations clean requires --ingestion-key"))?;
    let config = LoaderConfig::try_from(&config)?;
    let fs = ExposedDataPipeline::open_existing_declarations(&config.data_dir, ingestion_key.clone())?;
    let summary = DeclarationCleanerService::new(fs).clean_declarations().await?;
    Ok(CliSuccess::new(CleanedDeclarations {
        path: std::path::absolute(&config.data_dir)?.join(ingestion_key.to_string()).join("cleaned/declarations"),
        ingestion_key, member_partitions: summary.member_partitions,
        declarations: summary.declarations, funding_entries: summary.funding_entries, funders: summary.funders,
    }))
}

async fn members(stage: String, config: PathBuf, ingestion_key: Option<IngestionKey>)
    -> anyhow::Result<CliSuccess<StageAcknowledgement<MemberIngestionStage>>>
{
    let stage = MemberIngestionStage::from_str(&stage)?;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let data_dir = match stage {
        MemberIngestionStage::Fetch => {
            let config = FetcherConfig::try_from(&config)?;
            let api = ParliamentApiClient::new(config.batch_size)?;
            let fs = ExposedDataPipeline::new_with_ingestion_key(&config.data_dir, ingestion_key.clone())?;
            FetcherService::new(fs, api).fetch_members(&EntityIngestionRequest {}).await?;
            config.data_dir
        }
        MemberIngestionStage::Load => {
            let config = LoaderConfig::try_from(&config)?;
            let data_config = DataConfig::from_env()?;
            let fs = ExposedDataPipeline::new_with_ingestion_key(&config.data_dir, ingestion_key.clone())?;
            let db = ExposedDatabase::new(&data_config.connection_string).await;
            IngesterService::new(fs, db).load_members().await?;
            config.data_dir
        }
    };
    Ok(CliSuccess::new(StageAcknowledgement {
        path: std::path::absolute(data_dir)?.join(ingestion_key.to_string()).join("raw/members"),
        ingestion_key, stage,
    }))
}
